{
  "aktywnosci": [
    {
      "tytul": "Zabawa ruchowa „Kolorowe domki” z wykorzystaniem obręczy",
      "opis": "Nauczyciel rozkłada na dywanie kolorowe obręcze (czerwone, żółte, zielone i niebieskie), które pełnią rolę domków. Dzieci poruszają się swobodnie po sali w rytm tamburynu, naśladując latające motyle. Na przerwę w muzyce i hasło z nazwą koloru wypowiedziane przez nauczyciela, przedszkolaki jak najszybciej odnajdują i stają przy obręczy o wskazanej barwie."
    },
    {
      "tytul": "Eksperyment plastyczny „Czarowanie nowych barw”",
      "opis": "Dzieci otrzymują duże arkusze papieru oraz farby w trzech kolorach podstawowych: żółtym, niebieskim i czerwonym. Za pomocą pędzli lub gąbek nakładają plamy barwne obok siebie i delikatnie je łączą, obserwując powstawanie barw pochodnych: zielonej, pomarańczowej i fioletowej. Nauczyciel wspiera przedszkolaki w nazywaniu nowo powstałych kolorów i zachęca do swobodnego wypełnienia całej kartki tęczową kompozycją."
    },
    {
      "tytul": "Zabawa muzyczno-sensoryczna z chustą animacyjną „Tęczowa fala”",
      "opis": "Dzieci stają w kręgu, chwytają chustę animacyjną za krawędzie i delikatnie nią kołyszą w rytm spokojnej melodii śpiewanej przez nauczyciela. Gdy nauczyciel wymieni dany kolor, dzieci trzymające ten konkretny trójkąt chusty podnoszą ręce wysoko do góry, a pozostali kucają, tworząc barwną falę. Zabawa doskonali refleks, utrwala znajomość barw i uczy zgodnej współpracy w grupie."
    }
  ]
}
